// Example: idempotent processing sketch
async function processEvent(event, state) {
  const { eventId, tenantId, payload } = event;
  if (await state.hasProcessed(eventId)) return;
  await state.markProcessed(eventId);
  // transform and persist per-tenant
  await persistPerTenant(tenantId, payload);
}
```

